<script setup>
import { useAppStore } from '../stores/app.js'
const store=useAppStore();const baseUrl=import.meta.env.VITE_LLM_BASE_URL||'https://api.deepseek.com';const model=import.meta.env.VITE_LLM_MODEL_NAME||'deepseek-flash'
async function update(key,value){await store.updateSettings({[key]:value})}
</script>
<template><div class="page"><div class="page-header"><div><h2 class="page-title">系统设置</h2><p class="page-subtitle">按你的设备和习惯，调整专注体验。</p></div></div><div class="grid-2"><section class="surface surface-pad"><h3 class="section-title">体验开关</h3><div class="setting-row"><div><strong>摄像头监督默认状态</strong><p class="muted">专注页仍会再次展示隐私说明</p></div><el-switch :model-value="store.settings.cameraDefault" @change="value=>update('cameraDefault',value)"/></div><div class="setting-row"><div><strong>提醒音效</strong><p class="muted">视觉离岗时播放轻提示音</p></div><el-switch :model-value="store.settings.soundEnabled" @change="value=>update('soundEnabled',value)"/></div><div class="setting-row"><div><strong>AI 语音朗读</strong><p class="muted">答疑页点击朗读回答</p></div><el-switch :model-value="store.settings.ttsEnabled" @change="value=>update('ttsEnabled',value)"/></div><div class="setting-row"><div><strong>深色主题</strong><p class="muted">降低夜间学习时的屏幕刺激</p></div><el-switch :model-value="store.settings.darkMode" @change="value=>update('darkMode',value)"/></div></section><section class="surface surface-pad"><h3 class="section-title">性能与连接</h3><div class="setting-row"><div><strong>低配模式</strong><p class="muted">关闭 MediaPipe 视觉推理，仅保留页面切标签检测</p></div><el-switch :model-value="store.settings.lowPerformance" @change="value=>update('lowPerformance',value)"/></div><el-divider/><p class="muted">LLM 接口（只读展示）</p><div class="readonly-item"><span>Base URL</span><code>{{baseUrl}}</code></div><div class="readonly-item"><span>模型名称</span><code>{{model}}</code></div><el-alert type="info" :closable="false" style="margin-top:16px">API 密钥仅存放在后端 .env，前端不会接触密钥。</el-alert></section></div></div></template>
<style scoped>.setting-row{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:16px 0;border-bottom:1px solid var(--border)}.setting-row:last-child{border-bottom:0}.setting-row strong{font-size:14px}.setting-row p{margin:5px 0 0;font-size:12px}.readonly-item{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:12px;background:var(--surface-soft);margin:8px 0;border-radius:10px;font-size:13px}.readonly-item code{color:var(--primary);word-break:break-all}</style>
